  addInt('FBro填表_置属性', 'LB_FBro_FrameTianBiaoSetAttribute', 'long long object, const std::wstring& selector, int index, const std::wstring& name, const std::wstring& value', `${handle}, selector.c_str(), index, name.c_str(), value.c_str()`);
  addInt('FBro填表_触发事件', 'LB_FBro_FrameTianBiaoDispatchEvent', 'long long object, const std::wstring& selector, int index, const std::wstring& eventName, int keyCode', `${handle}, selector.c_str(), index, eventName.c_str(), keyCode`);
  addStringOut('FBro缓冲_转文本', 'LB_FBro_BufferToText', 'long long object', `static_cast<LB_FBRO_BUFFER_HANDLE>(object)`);
  add('std::wstring', 'FBro_取启动命令行', '', 'wchar_t value[16384] = {}; LB_FBro_GetStartupCommandLine(value, 16384); return value;', 'return L"";');
  addInt('FBro菜单_添加项', 'LB_FBro_MenuModelAddItem', 'long long object, int commandId, const std::wstring& label', `${handle}, commandId, label.c_str()`);
  addHandleResult('FBro菜单_添加子菜单', 'LB_FBro_MenuModelAddSubMenu', 'long long object, int commandId, const std::wstring& label', `${handle}, commandId, label.c_str()`);
  addInt('FBro菜单_设置加速键', 'LB_FBro_MenuModelSetAccelerator', 'long long object, int commandId, int keyCode, bool shift, bool ctrl, bool alt', `${handle}, commandId, keyCode, shift, ctrl, alt`);
  addStringOut('FBro菜单_取颜色', 'LB_FBro_MenuModelGetColor', 'long long object, int commandId, int colorType', `${handle}, commandId, colorType`);
  addInt('FBro菜单_清空', 'LB_FBro_MenuModelClear', 'long long object', `${handle}`);
  addInt('FBro菜单_取数量', 'LB_FBro_MenuModelGetCount', 'long long object', `${handle}`);
  addInt('FBro菜单_添加分隔栏', 'LB_FBro_MenuModelAddSeparator', 'long long object', `${handle}`);
  addInt('FBro菜单_添加复选项', 'LB_FBro_MenuModelAddCheckItem', 'long long object, int commandId, const std::wstring& label', `${handle}, commandId, label.c_str()`);
  addInt('FBro菜单_添加单选项', 'LB_FBro_MenuModelAddRadioItem', 'long long object, int commandId, const std::wstring& label, int groupId', `${handle}, commandId, label.c_str(), groupId`);
